	private static void assertBoundContextCounts(NativeLmdbQuerySource source, long object, long context)
			throws Exception {
		assertThat(source.count(-1, -1, -1, context)).as("the complete named context has four statements")
				.isEqualTo(4);
		assertThat(source.count(-1, -1, object, -1)).as("the bound object appears in four statements across graphs")
				.isEqualTo(4);
		long matched = 0;
		try (RecordIterator rows = source.statements(-1, -1, object, context)) {
			while (rows.next() != null) {
				matched++;
			}
		}
		assertThat(matched).isEqualTo(2);
		assertThat(source.count(-1, -1, object, context))
				.as("an inline object is a bound term, so the whole-context total is not its count")
				.isEqualTo(matched);
		assertThat(source.count(-1, -1, object, 0)).as("the same bound-object rule applies to the default context")
				.isEqualTo(1);
	}
